// TableView.js
import React, { useMemo, useState, useEffect } from "react";

export default function TableView({ rows = [], initialRowsPerPage = 10 }) {
  const [query, setQuery] = useState("");
  const [sortBy, setSortBy] = useState({ key: null, dir: null });
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(initialRowsPerPage);
  const [visibleCols, setVisibleCols] = useState(null);

  useEffect(() => {
    setPage(0);
    setVisibleCols(null);
  }, [rows]);

  if (!rows || rows.length === 0) {
    return <div className="text-muted small">No matching rows. Try a different area or upload data.</div>;
  }

  const augmented = useMemo(() => rows.map((r, i) => ({ __idx: i, ...r })), [rows]);
  const allCols = useMemo(() => Object.keys(augmented[0] || {}).filter((c) => c !== "__idx"), [augmented]);

  useEffect(() => {
    if (visibleCols === null) {
      const initial = {};
      allCols.forEach((c) => (initial[c] = true));
      setVisibleCols(initial);
    }
  }, [allCols, visibleCols]);

  const visibleColumnList = useMemo(() => {
    if (!visibleCols) return allCols;
    return allCols.filter((c) => visibleCols[c]);
  }, [allCols, visibleCols]);

  const filtered = useMemo(() => {
    if (!query) return augmented;
    const q = query.toLowerCase();
    return augmented.filter((row) => visibleColumnList.some((col) => String(row[col] ?? "").toLowerCase().includes(q)));
  }, [augmented, query, visibleColumnList]);

  const sorted = useMemo(() => {
    if (!sortBy.key) return filtered;
    const key = sortBy.key;
    const dir = sortBy.dir === "desc" ? -1 : 1;
    const copy = [...filtered];
    copy.sort((a, b) => {
      const va = a[key];
      const vb = b[key];
      const na = parseFloat(va);
      const nb = parseFloat(vb);
      if (!isNaN(na) && !isNaN(nb)) return (na - nb) * dir;
      const da = Date.parse(String(va));
      const db = Date.parse(String(vb));
      if (!isNaN(da) && !isNaN(db)) return (da - db) * dir;
      return String(va ?? "").localeCompare(String(vb ?? "")) * dir;
    });
    return copy;
  }, [filtered, sortBy]);

  const pageCount = Math.max(1, Math.ceil(sorted.length / rowsPerPage));
  useEffect(() => {
    if (page >= pageCount) setPage(Math.max(0, pageCount - 1));
  }, [pageCount, page]);

  const pageRows = useMemo(() => {
    const start = page * rowsPerPage;
    return sorted.slice(start, start + rowsPerPage);
  }, [sorted, page, rowsPerPage]);

  const toggleCol = (col) => setVisibleCols((prev) => ({ ...prev, [col]: !prev[col] }));

  const exportCSV = () => {
    const cols = visibleColumnList;
    const rowsToExport = sorted;
    const csvRows = [cols.join(",")];
    for (const r of rowsToExport) {
      const values = cols.map((c) => {
        const v = r[c];
        if (v == null) return "";
        const s = String(v).replace(/"/g, '""');
        return `"${s}"`;
      });
      csvRows.push(values.join(","));
    }
    const blob = new Blob([csvRows.join("\n")], { type: "text/csv" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `table-${Date.now()}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="card shadow-sm border-0 rounded-3">
      <div className="card-body">
        <div className="d-flex justify-content-between align-items-center mb-2">
          <div className="input-group" style={{ minWidth: 340 }}>
            <span className="input-group-text"><i className="bi bi-search" /></span>
            <input placeholder="Search table..." value={query} onChange={(e) => setQuery(e.target.value)} className="form-control form-control-sm" />
            <button className="btn btn-outline-secondary btn-sm" onClick={() => { setQuery(""); setSortBy({ key: null, dir: null }); }}>Reset</button>
          </div>

          <div className="d-flex align-items-center gap-2">
            <div className="dropdown">
              <button className="btn btn-sm btn-outline-secondary dropdown-toggle" data-bs-toggle="dropdown">Columns</button>
              <ul className="dropdown-menu p-2">
                {allCols.map((c) => (
                  <li key={c} className="form-check">
                    <input className="form-check-input" type="checkbox" checked={!!visibleCols?.[c]} onChange={() => toggleCol(c)} id={`col-${c}`} />
                    <label className="form-check-label small" htmlFor={`col-${c}`}>{c}</label>
                  </li>
                ))}
              </ul>
            </div>

            <div className="btn-group">
              <button className="btn btn-sm btn-outline-success" onClick={exportCSV}>Export CSV</button>
            </div>
          </div>
        </div>

        <div style={{ maxHeight: 320, overflow: "auto" }}>
          <table className="table table-sm table-hover mb-0">
            <thead className="table-light sticky-top">
              <tr>
                {visibleColumnList.map((col) => (
                  <th key={col} style={{ cursor: "pointer" }} onClick={() => setSortBy((prev) => (prev.key !== col ? { key: col, dir: "asc" } : prev.dir === "asc" ? { key: col, dir: "desc" } : { key: null, dir: null }))}>
                    <div className="d-flex align-items-center gap-2">
                      <span>{col}</span>
                      <small className="text-muted">
                        {sortBy.key === col ? (sortBy.dir === "asc" ? "▲" : "▼") : ""}
                      </small>
                    </div>
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {pageRows.map((r) => (
                <tr key={r.__idx}>
                  {visibleColumnList.map((col) => (
                    <td key={col} style={{ whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis", maxWidth: 220 }}>{String(r[col] ?? "")}</td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        <div className="d-flex justify-content-between align-items-center mt-2">
          <div className="small text-muted">Showing {sorted.length} rows</div>
          <div className="d-flex align-items-center gap-2">
            <select className="form-select form-select-sm" value={rowsPerPage} onChange={(e) => { setRowsPerPage(Number(e.target.value)); setPage(0); }}>
              {[5, 10, 25, 50].map((n) => <option key={n} value={n}>{n}</option>)}
            </select>
            <button className="btn btn-sm btn-outline-primary" onClick={() => setPage((p) => Math.max(0, p - 1))} disabled={page === 0}>Prev</button>
            <div className="small">{page + 1} / {pageCount}</div>
            <button className="btn btn-sm btn-outline-primary" onClick={() => setPage((p) => Math.min(pageCount - 1, p + 1))} disabled={page >= pageCount - 1}>Next</button>
          </div>
        </div>
      </div>
    </div>
  );
}
